import sys, time
from collections import defaultdict
sys.path.insert(0, "src")
from rollup import load_rows
rows = load_rows("data/ledger.csv")

def summarise(rows):
    counts = {}
    totals = {}
    peaks = {}
    regions = {}
    seen = {}
    for row in rows:
        a = row.account
        if a in counts:
            counts[a] += 1
            totals[a] += row.amount_cents
            if row.amount_cents > peaks[a]:
                peaks[a] = row.amount_cents
            r = row.region
            if r not in seen[a]:
                seen[a].add(r)
                regions[a].append(r)
        else:
            counts[a] = 1
            totals[a] = row.amount_cents
            peaks[a] = row.amount_cents
            regions[a] = [row.region]
            seen[a] = {row.region}
    return {a: (counts[a], totals[a], peaks[a], tuple(regions[a])) for a in counts}

t = time.perf_counter()
s = summarise(rows)
print("variant2 (per-field dicts):", time.perf_counter() - t, len(s))
EOF
